from lesson_authoring import entry as E
B=[['希腊 polos → 拉丁 polus','旋转轴；轴端'],['中世纪拉丁 polaris／法语 polaire','极点相关的']]
P=B+[['法语 polariser → 英语 polarize','使产生偏振或极性'],['社会用法','使分向明显对立的两边']]
S=['https://www.etymonline.com/word/polarize','https://www.oxfordlearnersdictionaries.com/definition/english/polarize']
W=[
E('polar','英 /ˈpəʊlə/；美 /ˈpoʊlər/','极地的；极性的；完全相反的','先想象地球转轴的两端，再想到两种性质离得很远、方向相反。','来自法语 polaire 或中世纪拉丁 polaris；上接 polus 轴端，不是从英语 police 警察截取。',B+[['英语 polar','极地相关的；有极性；两极对立的']],'polar regions 是极地地区；polar opposites 是截然相反的两个人或事物；a polar molecule 是有极性的分子。不同场景保留“极”的联系，但不能把每个 polar 都译成寒冷。','polar regions；a polar bear；polar opposites；a polar molecule。','polar 的地理义可涉及南北两极，Arctic 专指北极地区。polar opposites 强调差异极大，不必真有两个地理极点。',('The research team studies changes in the polar regions.','研究团队研究极地地区的变化。'),('Their personalities are polar opposites.','他们的性格截然相反。'),sources=['https://www.etymonline.com/word/polar','https://en.wiktionary.org/wiki/polar']),
E('polarity','英 /pəˈlærəti/；美 /pəˈlærəti/','极性；两极对立','把两端的性质标出来：这边是正，那边是负，方向不能随意弄反。','polar + -ity，把有极性的特征变成名词；重音从 polar 的前面移到 /lær/。',B+[['polar → polarity','极性的 → 极性这一属性']],'battery polarity 是电池的正负极性；reverse the polarity 是把极性反过来。谈观点时也可表示两极对立，但普通意见不同不必都上升到 polarity。','reverse polarity；magnetic polarity；electrical polarity；opposite polarity。','polarity 常说已经具有的属性或方向，polarization 常说形成这种状态的过程，或某一学科中的相关现象。',('The diagram marks the polarity of each terminal.','图示标明了各接线端的极性。'),('The sensor can detect a change in magnetic polarity.','这个传感器能检测磁极性的变化。'),sources=['https://www.etymonline.com/word/polarity','https://en.wiktionary.org/wiki/polarity']),
E('polarize','英 /ˈpəʊləraɪz/；美 /ˈpoʊləraɪz/','使两极分化；使产生偏振；使极化','在人群中，像把分散的意见拉向两边；在光学中，则说光振动方向的性质发生变化。','借自法语 polariser，接 polaris；现代可分析为 polar + -ize。最初是光学术语，社会分化义后来发展。',P,'polarize voters 是使选民形成更尖锐的对立；polarize light 是使光产生偏振。社会义的“两派站队”适合记忆，但不能拿来当光学定义：光没有政治上的两种意见。','polarize opinion；polarize voters；polarize a community；polarize light。','polarize 不只是 provoke 引起反应，而是突出反应朝对立方向分化。英式英语也常写 polarise，读音一样。',('The proposal could polarize an already divided community.','这项提案可能让原本就有分歧的社区更加对立。'),('The experiment used a filter to polarize the light.','实验使用滤光片使光产生偏振。'),sources=S+['https://openstax.org/books/university-physics-volume-3/pages/1-7-polarization']),
E('polarise','英 /ˈpəʊləraɪz/；美 /ˈpoʊləraɪz/','使两极分化；使偏振或极化〔常见英式拼写〕','同一个议题让赞成者和反对者越站越远，中间的立场越来越难容纳。','polarize 的 -ise 拼写形式，沿同一法语 polariser 路线；不是新词源或另一个意思。',P[:-1]+[['英语 polarise〔与 polarize 同词〕','使分化为对立两边；使偏振']],'The debate polarises people 表示这场辩论使人们的意见走向对立。选择 -ise 拼写时，相应词形通常是 polarised、polarising、polarisation，篇内保持一致即可。','polarise public opinion；polarise the debate；polarise society。','polarise 与 polarize 的差异主要在拼写习惯，s 在这里仍读 /z/，不要读成 /s/。',('The campaign threatens to polarise the town.','这场宣传活动可能使镇上的人形成更明显的对立。'),('The article asks why a single issue can polarise public opinion.','文章探讨为什么一个议题就能使公众意见两极分化。'),sources=S+['https://en.wiktionary.org/wiki/polarise']),
E('polarization','英 /ˌpəʊləraɪˈzeɪʃən/；美 /ˌpoʊlərəˈzeɪʃən/','两极分化；偏振；极化','新闻里看两边越分越开，物理课里则要看说的是光的振动还是电荷的分布。','可接 polarize + -ation，也部分借自法语 polarisation；不能一概只画成英语动词的后造名词。',B+[['法语 polarisation／英语 polarize + -ation','偏振、极化等术语'],['社会语境的 polarization','立场差异加深、形成两极']],'political polarization 是政治立场两极化。光的 polarization 涉及电场振动的方向特征；材料中的电极化则涉及电荷分布或偶极取向。这些专业用法应分开，不要只靠“分成两堆”解释全部现象。','political polarization；social polarization；polarization of light；electric polarization。','polarization 是过程、状态或现象名称；polarized 是形容已经处于这种状态。光学的偏振不等于把光分成正负电荷。',('The study examines increasing political polarization.','这项研究考察日益加深的政治两极化。'),('The class used filters to investigate the polarization of light.','课堂上用滤光片研究光的偏振。'),sources=['https://www.etymonline.com/word/polarization','https://openstax.org/books/university-physics-volume-3/pages/1-7-polarization','https://en.wiktionary.org/wiki/polarization']),
E('polarisation','英 /ˌpəʊləraɪˈzeɪʃən/；美 /ˌpoʊlərəˈzeɪʃən/','两极分化；偏振；极化〔常见英式拼写〕','把“逐渐分向两边”作为一个现象来讨论，而不是只说某个人正在争吵。','polarization 的 -isation 拼写形式；与 polarise、polarised 对应，同样保留法语与英语构词两条近源说明。',B+[['法语 polarisation／英语 polarise + -ation','偏振、极化的名词'],['英语社会用法','两极分化现象']],'social polarisation 可以讨论群体之间的分化；light polarisation 则是光学主题。拼写里的 s 不改变含义，也不会让政治义变成另一种分化机制。','social polarisation；political polarisation；reduce polarisation；light polarisation。','polarisation 和 polarization 是同词的常见拼写差异，读音基本相同。选一种写法后，与动词形式尽量保持一致。',('The report links the crisis to growing social polarisation.','报告把这场危机与加剧的社会两极分化联系起来。'),('The workshop included a demonstration of light polarisation.','研讨课安排了一次光偏振演示。'),sources=['https://www.etymonline.com/word/polarization','https://en.wiktionary.org/wiki/polarisation'])
]
